from pathlib import Path
import json

root = Path('/home/ubuntu/stargatewars')
data = json.loads((root / 'schema_graph.json').read_text())
# Group tables for a readable architecture view.
groups = {
    'Identity & Navigation': {'races','players','player_resources','player_unit_stats','menu_items','page_content','rank_definitions','game_settings'},
    'Technology & Fleet': {'player_technologies','technologies','weapon_types','player_weapons','motherships','mothership_modules'},
    'Planets & World': {'player_planets','planet_bonuses','planet_defenses','planet_explorations','target_realms'},
    'Political & Social': {'alliances','alliance_members','commander_relationships','officer_relationships','recruitment_records','messages','blacklists','ip_restrictions'},
    'Combat': {'battles','battle_participants','battle_reports','attack_logs'},
    'Covert': {'covert_agents','anti_covert_agents','spy_missions','sabotage_missions','covert_missions','intelligence_reports'},
    'Market & Mercenaries': {'market_orders','private_trades','mercenary_types','player_mercenaries','alliances_black_market'},
    'Progression & Audit': {'rankings','rank_snapshots','glory_reputation','ascensions','ascension_states','supporter_status','protection_states','vacation_states','game_turns','turn_events','game_events','audit_logs'},
}
for t in data['tables']:
    t['group'] = next((g for g, names in groups.items() if t['name'] in names), 'Other')
data['groups'] = list(groups.keys())
html = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>StargateWars — 54-Table Schema Explorer</title><style>
:root{--ink:#111;--muted:#686868;--line:#d9d9d9;--paper:#fff;--soft:#f6f6f4;--blue:#163d72;--gold:#99721c}*{box-sizing:border-box}body{margin:0;background:var(--soft);color:var(--ink);font:14px/1.4 Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif}.shell{max-width:1600px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:20px;align-items:end;border-bottom:1px solid var(--line);padding-bottom:18px}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font-size:10px;color:var(--muted);font-weight:700}.top h1{font-size:30px;line-height:1;margin:8px 0 0}.stats{display:flex;gap:8px}.stat{border:1px solid var(--line);background:var(--paper);padding:10px 14px;min-width:105px}.stat b{display:block;font-size:22px}.stat span{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.toolbar{display:flex;gap:10px;align-items:center;padding:18px 0}.toolbar input{flex:1;border:1px solid #bbb;padding:12px 14px;background:#fff;color:#111}.toolbar button{border:1px solid #111;background:#111;color:#fff;padding:12px 14px;cursor:pointer}.toolbar button.alt{background:#fff;color:#111}.legend{display:flex;gap:8px;flex-wrap:wrap}.legend button{border:1px solid var(--line);background:#fff;padding:7px 10px;cursor:pointer}.legend button.active{border-color:#111;box-shadow:inset 0 -2px #111}.layout{display:grid;grid-template-columns:320px 1fr;gap:18px}.panel{background:#fff;border:1px solid var(--line);padding:16px}.sidebar{max-height:calc(100vh - 170px);overflow:auto;position:sticky;top:20px}.group h2{font-size:11px;text-transform:uppercase;letter-spacing:.13em;color:var(--muted);margin:16px 0 8px}.table-row{display:flex;justify-content:space-between;gap:8px;border-bottom:1px solid #eee;padding:8px 0;cursor:pointer}.table-row:hover,.table-row.selected{background:#f0f3f7}.table-row b{font-size:12px}.table-row small{color:var(--muted)}.canvas-wrap{overflow:auto;border:1px solid var(--line);background:#fbfbfa;min-height:780px}.canvas{position:relative;width:1500px;height:1220px}.canvas svg{position:absolute;inset:0;pointer-events:none}.edge{stroke:#b5b5b5;stroke-width:1.2;opacity:.42}.edge.active{stroke:var(--blue);stroke-width:2.4;opacity:1}.node{position:absolute;width:180px;background:#fff;border:1px solid #bbb;box-shadow:0 2px 7px #0000000d;cursor:pointer;z-index:2}.node h3{font-size:12px;margin:0;padding:9px 10px;border-bottom:1px solid #e7e7e7}.node .group-tag{font-size:9px;color:var(--gold);text-transform:uppercase;letter-spacing:.08em;padding:7px 10px 0}.node ul{margin:6px 10px 10px;padding:0;list-style:none;color:#666;font-size:10px;max-height:92px;overflow:hidden}.node li{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.node.selected{border:2px solid var(--blue);box-shadow:0 0 0 3px #163d7220}.node.dim{opacity:.18}.details{margin-top:18px}.details h2{margin:0 0 5px;font-size:20px}.details p{margin:0;color:var(--muted)}.relations{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.chip{border:1px solid var(--line);padding:6px 8px;background:#fafafa;font-size:11px}.empty{color:var(--muted);padding:20px;text-align:center}.notice{padding:9px 12px;background:#fff;border-left:3px solid #111;margin-bottom:12px;color:#555;font-size:12px}@media(max-width:1000px){.layout{grid-template-columns:1fr}.sidebar{position:static;max-height:none}.top{display:block}.stats{margin-top:15px}.canvas-wrap{min-height:600px}}
</style></head><body><main class="shell"><header class="top"><div><div class="eyebrow">STARGATEWARS / DATA ARCHITECTURE</div><h1>54-Table Schema Explorer</h1></div><div class="stats"><div class="stat"><b id="tableCount"></b><span>Tables</span></div><div class="stat"><b id="relationCount"></b><span>Relationships</span></div><div class="stat"><b id="groupCount"></b><span>Systems</span></div></div></header><div class="toolbar"><input id="search" placeholder="Search tables, columns, or systems…"><button id="reset">Reset view</button><div class="legend" id="legend"></div></div><div class="notice">Click a table to highlight its foreign-key relationships. Use the search field to filter the table list and dim unrelated nodes in the diagram.</div><section class="layout"><aside class="panel sidebar" id="sidebar"></aside><section><div class="canvas-wrap"><div class="canvas" id="canvas"><svg id="edges" viewBox="0 0 1500 1220" preserveAspectRatio="none"></svg></div></div><div class="panel details" id="details"><h2>Select a table</h2><p>Choose a table from the list or diagram to inspect its columns and relationships.</p></div></section></section></main><script>const graph=__GRAPH__;const colors=['#163d72','#7a4e13','#2d6a4f','#812d4b','#5a4b8a','#8a5a22','#2c5f7a','#444'];const byName=Object.fromEntries(graph.tables.map(t=>[t.name,t]));const groupColor=Object.fromEntries(graph.groups.map((g,i)=>[g,colors[i%colors.length]]));const pos={};const canvas=document.getElementById('canvas');const edges=document.getElementById('edges');document.getElementById('tableCount').textContent=graph.table_count;document.getElementById('relationCount').textContent=graph.relationship_count;document.getElementById('groupCount').textContent=graph.groups.length;function layout(){const cols=7, w=205,h=145;graph.tables.forEach((t,i)=>{pos[t.name]={x:20+(i%cols)*w,y:20+Math.floor(i/cols)*h};});}function renderSidebar(filter=''){const side=document.getElementById('sidebar');side.innerHTML='';graph.groups.forEach(g=>{const list=graph.tables.filter(t=>t.group===g&&(!filter||JSON.stringify(t).toLowerCase().includes(filter)));if(!list.length)return;const sec=document.createElement('div');sec.className='group';sec.innerHTML='<h2>'+g+'</h2>';list.forEach(t=>{const row=document.createElement('div');row.className='table-row';row.dataset.table=t.name;row.innerHTML='<b>'+t.name+'</b><small>'+t.columns.length+' cols</small>';row.onclick=()=>select(t.name);sec.appendChild(row);});side.appendChild(sec);});if(!side.children.length)side.innerHTML='<div class="empty">No tables match the search.</div>';}
function renderLegend(){const l=document.getElementById('legend');graph.groups.forEach(g=>{const b=document.createElement('button');b.textContent=g;b.dataset.group=g;b.style.borderBottom='3px solid '+groupColor[g];b.onclick=()=>{document.getElementById('search').value='';document.querySelectorAll('.node').forEach(n=>n.classList.toggle('dim',n.dataset.group!==g));};l.appendChild(b);});}
function renderNodes(){graph.tables.forEach(t=>{const n=document.createElement('article');n.className='node';n.dataset.table=t.name;n.dataset.group=t.group;n.style.left=pos[t.name].x+'px';n.style.top=pos[t.name].y+'px';n.innerHTML='<div class="group-tag" style="color:'+groupColor[t.group]+'">'+t.group+'</div><h3>'+t.name+'</h3><ul>'+t.columns.slice(0,7).map(c=>'<li>'+c.name+' <span>'+c.type+'</span></li>').join('')+'</ul>';n.onclick=()=>select(t.name);canvas.appendChild(n);});}
function renderEdges(){graph.relationships.forEach(r=>{const a=pos[r.from_table],b=pos[r.to_table];if(!a||!b)return;const x1=a.x+90,y1=a.y+70,x2=b.x+90,y2=b.y+70;const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.classList.add('edge');line.dataset.from=r.from_table;line.dataset.to=r.to_table;line.setAttribute('x1',x1);line.setAttribute('y1',y1);line.setAttribute('x2',x2);line.setAttribute('y2',y2);edges.appendChild(line);});}
function select(name){document.querySelectorAll('.node').forEach(n=>n.classList.toggle('selected',n.dataset.table===name));document.querySelectorAll('.table-row').forEach(n=>n.classList.toggle('selected',n.dataset.table===name));const rel=graph.relationships.filter(r=>r.from_table===name||r.to_table===name);document.querySelectorAll('.edge').forEach(e=>e.classList.toggle('active',rel.some(r=>(r.from_table===e.dataset.from&&r.to_table===e.dataset.to))));const t=byName[name];document.getElementById('details').innerHTML='<h2>'+name+'</h2><p><b>'+t.group+'</b> · '+t.columns.length+' columns · '+rel.length+' relationships</p><div class="relations">'+rel.map(r=>'<span class="chip">'+r.from_table+'.'+r.from_column+' → '+r.to_table+'.'+r.to_column+'</span>').join('')+'</div><h3>Columns</h3><div class="relations">'+t.columns.map(c=>'<span class="chip">'+c.name+' · '+c.type+'</span>').join('')+'</div>';}
function filter(){const q=document.getElementById('search').value.toLowerCase().trim();renderSidebar(q);document.querySelectorAll('.node').forEach(n=>{const t=byName[n.dataset.table];n.classList.toggle('dim',!!q&&!JSON.stringify(t).toLowerCase().includes(q));});}layout();renderLegend();renderSidebar();renderNodes();renderEdges();document.getElementById('search').oninput=filter;document.getElementById('reset').onclick=()=>{document.getElementById('search').value='';document.querySelectorAll('.node,.edge').forEach(n=>n.classList.remove('dim','selected','active'));document.getElementById('details').innerHTML='<h2>Select a table</h2><p>Choose a table from the list or diagram to inspect its columns and relationships.</p>';renderSidebar();};</script></body></html>'''.replace('__GRAPH__', json.dumps(data))
(root / 'schema-explorer.html').write_text(html)
print(f'wrote {root / "schema-explorer.html"} with {data["table_count"]} tables and {data["relationship_count"]} relationships')
